#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricChargeDensity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricChargeDensity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricChargeDensityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricChargeDensity::from_base(0.0).auto_unit().unit,
        ElectricChargeDensityUnit::CoulombPerCubicMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "C/m³".parse::<ElectricChargeDensityUnit>(),
        Ok(ElectricChargeDensityUnit::CoulombPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "C/m³").parse::<ElectricChargeDensity>(),
        Ok(ElectricChargeDensity::new(
            2.5,
            ElectricChargeDensityUnit::CoulombPerCubicMeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricChargeDensity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricChargeDensity::from_base(6.0);
    let b = ElectricChargeDensity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricChargeDensity::<i64>::from_base(7);
    let b = ElectricChargeDensity::<i64>::from_base(2);
    assert_eq!(a + b, ElectricChargeDensity::from_base(9));
    assert_eq!(a % b, ElectricChargeDensity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricChargeDensity<i64>>(),
        ElectricChargeDensity::from_base(9)
    );
}
